namespace RaceDay.Api.Models;

public class Role { public int RoleID { get; set; } public string RoleName { get; set; } = "Participant"; public List<User> Users { get; set; } = []; }
public class User { public int UserID { get; set; } public int RoleID { get; set; } public Role? Role { get; set; } public string FirstName { get; set; } = ""; public string LastName { get; set; } = ""; public string Email { get; set; } = ""; public string PasswordHash { get; set; } = ""; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<RaceEvent> OrganisedEvents { get; set; } = []; }
public class RaceEvent { public int EventID { get; set; } public int OrganiserID { get; set; } public User? Organiser { get; set; } public string EventName { get; set; } = ""; public string? Description { get; set; } public DateTime EventDate { get; set; } public string Location { get; set; } = ""; public string Status { get; set; } = "Open"; public DateTime CreatedAt { get; set; } = DateTime.UtcNow; public List<EventCategory> EventCategories { get; set; } = []; }
public class Category { public int CategoryID { get; set; } public int CreatedByUserID { get; set; } public User? CreatedByUser { get; set; } public string CategoryName { get; set; } = ""; public decimal DistanceKm { get; set; } public List<EventCategory> EventCategories { get; set; } = []; }
public class EventCategory { public int EventID { get; set; } public RaceEvent? Event { get; set; } public int CategoryID { get; set; } public Category? Category { get; set; } public decimal EntryFee { get; set; } public int Capacity { get; set; } public List<Enrolment> Enrolments { get; set; } = []; }
public class Enrolment { public int EnrolmentID { get; set; } public int EventID { get; set; } public int CategoryID { get; set; } public int ParticipantID { get; set; } public User? Participant { get; set; } public EventCategory? EventCategory { get; set; } public DateTime EnrolmentDate { get; set; } = DateTime.UtcNow; public string Status { get; set; } = "Confirmed"; public RaceResult? Result { get; set; } }
public class RaceResult { public int ResultID { get; set; } public int EnrolmentID { get; set; } public Enrolment? Enrolment { get; set; } public TimeSpan? FinishTime { get; set; } public int? Position { get; set; } public string Status { get; set; } = "Recorded"; public DateTime RecordedAt { get; set; } = DateTime.UtcNow; }
